import{_ as e,c as i,o as n,a0 as r}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice.","frontmatter":{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice."},"headers":[],"relativePath":"de/blog/inner-critic.md","filePath":"de/blog/inner-critic.md"}');const a=e({name:"de/blog/inner-critic.md"},[["render",function(e,t,a,s,u,l){return n(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="den-inneren-kritiker-verstehen" tabindex="-1">Den inneren Kritiker verstehen <a class="header-anchor" href="#den-inneren-kritiker-verstehen" aria-label="Permalink to &quot;Den inneren Kritiker verstehen&quot;">​</a></h1><p>Jeder Boule-Spieler kennt diese Stimme. Die, die flüstert: „Du wirst verfehlen“, kurz bevor man wirft. Die, die den letzten Fehlwurf in einer Endlosschleife wiederholt. Das ist dein innerer Kritiker – und zu lernen, ihn zu kontrollieren, ist entscheidend für Höchstleistungen.</p><h2 id="was-ist-der-innere-kritiker" tabindex="-1">Was ist der innere Kritiker? <a class="header-anchor" href="#was-ist-der-innere-kritiker" aria-label="Permalink to &quot;Was ist der innere Kritiker?&quot;">​</a></h2><p>Der innere Kritiker ist jene innere Stimme, die urteilt, kritisiert und Ihr Selbstvertrauen untergräbt. Beim Boule taucht sie oft im ungünstigsten Moment auf:</p><ul><li><strong>Vor einem entscheidenden Schuss:</strong> „Alle schauen zu. Vermassel das nicht.“</li><li><strong>Nach einem Fehlschuss:</strong> „Du versagst immer unter Druck.“</li><li><strong>Während einer Pechsträhne:</strong> „Du bist nicht gut genug für dieses Niveau.“</li></ul><p>Diese Stimme will dich nicht verletzen – sie ist vielmehr ein fehlgeleiteter Schutzmechanismus. Dein Gehirn versucht, dich auf ein Scheitern vorzubereiten, damit es nicht so weh tut. Doch dieser „Schutz“ führt zu Selbstsabotage.</p><h2 id="seine-muster-erkennen" tabindex="-1">Seine Muster erkennen <a class="header-anchor" href="#seine-muster-erkennen" aria-label="Permalink to &quot;Seine Muster erkennen&quot;">​</a></h2><p>Der erste Schritt ist Bewusstsein. Achten Sie darauf, wann Ihr innerer Kritiker auftaucht:</p><h3 id="haufige-ausloser" tabindex="-1">Häufige Auslöser <a class="header-anchor" href="#haufige-ausloser" aria-label="Permalink to &quot;Häufige Auslöser&quot;">​</a></h3><ul><li>Hochdrucksituationen (Matchball, wichtige Turniere)</li><li>Nachdem ich einen Fehler gemacht hatte</li><li>Wenn die Gegner gut spielen</li><li>Wenn Teamkollegen frustriert wirken</li><li>Körperliche Erschöpfung oder Beschwerden</li></ul><h3 id="haufige-nachrichten" tabindex="-1">Häufige Nachrichten <a class="header-anchor" href="#haufige-nachrichten" aria-label="Permalink to &quot;Häufige Nachrichten&quot;">​</a></h3><ul><li>&quot;Du kannst mit Druck nicht umgehen.&quot;</li><li>&quot;Du bist nicht so gut wie sie.&quot;</li><li>&quot;Alle verurteilen dich.&quot;</li><li>&quot;Du versagst immer, wenn es darauf ankommt.&quot;</li></ul><h2 id="die-auswirkungen-auf-die-leistung" tabindex="-1">Die Auswirkungen auf die Leistung <a class="header-anchor" href="#die-auswirkungen-auf-die-leistung" aria-label="Permalink to &quot;Die Auswirkungen auf die Leistung&quot;">​</a></h2><p>Wenn der innere Kritiker die Oberhand gewinnt, reagiert Ihr Körper:</p><ol><li><strong>Die Muskelspannung nimmt zu</strong> – Dein Wurf wird steifer</li><li><strong>Die Atmung wird flach</strong> – Weniger Sauerstoff, weniger Konzentration</li><li><strong>Das Sichtfeld verengt sich</strong> – Man verliert die Orientierung im Gelände.</li><li><strong>Die Entscheidungsfindung leidet</strong> – Man zweifelt an sich selbst.</li></ol><p>Dadurch entsteht ein Teufelskreis: Der innere Kritiker verursacht schlechte Leistungen, was dem Kritiker wiederum mehr Munition liefert.</p><h2 id="strategien-zum-umgang-mit-dem-inneren-kritiker" tabindex="-1">Strategien zum Umgang mit dem inneren Kritiker <a class="header-anchor" href="#strategien-zum-umgang-mit-dem-inneren-kritiker" aria-label="Permalink to &quot;Strategien zum Umgang mit dem inneren Kritiker&quot;">​</a></h2><h3 id="_1-benenne-es-um-es-zu-zahmen" tabindex="-1">1. Benenne es, um es zu zähmen <a class="header-anchor" href="#_1-benenne-es-um-es-zu-zahmen" aria-label="Permalink to &quot;1. Benenne es, um es zu zähmen&quot;">​</a></h3><p>Gib deinem inneren Kritiker einen Namen – etwas leicht Absurdes. „Oh je, da meldet sich der Miesepeter schon wieder.“ Das schafft Distanz zwischen dir und dieser Stimme und macht es dir leichter, sie zu ignorieren.</p><h3 id="_2-die-beweise-hinterfragen" tabindex="-1">2. Die Beweise hinterfragen <a class="header-anchor" href="#_2-die-beweise-hinterfragen" aria-label="Permalink to &quot;2. Die Beweise hinterfragen&quot;">​</a></h3><p>Wenn der Kritiker sagt: „Du versagst immer unter Druck“, frag dich selbst: Stimmt das wirklich? Kannst du dich an Situationen erinnern, in denen du unter Druck gut gespielt hast? Der Kritiker argumentiert mit Absolutismen, die selten der Realität entsprechen.</p><h3 id="_3-die-botschaft-neu-formulieren" tabindex="-1">3. Die Botschaft neu formulieren <a class="header-anchor" href="#_3-die-botschaft-neu-formulieren" aria-label="Permalink to &quot;3. Die Botschaft neu formulieren&quot;">​</a></h3><p>Kritik in Coaching umwandeln:</p><ul><li>&quot;Das wirst du verpassen&quot; → &quot;Konzentriere dich auf deine Routine&quot;</li><li>&quot;Alle schauen zu&quot; → &quot;Jetzt ist deine Chance zu glänzen&quot;</li><li>&quot;Du versagst immer.&quot; → &quot;Du hast schon öfter mit Drucksituationen umgegangen.&quot;</li></ul><h3 id="_4-wenden-sie-ihre-pre-spritz-routine-an" tabindex="-1">4. Wenden Sie Ihre Pre-Spritz-Routine an. <a class="header-anchor" href="#_4-wenden-sie-ihre-pre-spritz-routine-an" aria-label="Permalink to &quot;4. Wenden Sie Ihre Pre-Spritz-Routine an.&quot;">​</a></h3><p>Eine solide Vorbereitungsroutine gibt Ihrem Geist etwas Konstruktives, worauf er sich konzentrieren kann, und lässt so weniger Raum für Kritiker.</p><h3 id="_5-ube-selbstmitgefuhl" tabindex="-1">5. Übe Selbstmitgefühl <a class="header-anchor" href="#_5-ube-selbstmitgefuhl" aria-label="Permalink to &quot;5. Übe Selbstmitgefühl&quot;">​</a></h3><p>Behandle dich selbst so, wie du einen Teamkollegen behandeln würdest. Würdest du einem Teamkollegen, der Probleme hat, sagen: „Du bist schrecklich“? Natürlich nicht. Sei genauso freundlich zu dir selbst.</p><h2 id="aufbau-einer-unterstutzenden-inneren-stimme" tabindex="-1">Aufbau einer unterstützenden inneren Stimme <a class="header-anchor" href="#aufbau-einer-unterstutzenden-inneren-stimme" aria-label="Permalink to &quot;Aufbau einer unterstützenden inneren Stimme&quot;">​</a></h2><p>Ziel ist es nicht, den inneren Kritiker völlig zum Schweigen zu bringen – das ist nahezu unmöglich. Vielmehr geht es darum, eine stärkere, unterstützende Stimme zu entwickeln:</p><h3 id="die-unterstutzende-stimme-sagt" tabindex="-1">Die unterstützende Stimme sagt: <a class="header-anchor" href="#die-unterstutzende-stimme-sagt" aria-label="Permalink to &quot;Die unterstützende Stimme sagt:&quot;">​</a></h3><ul><li>&quot;Ein Wurf nach dem anderen&quot;</li><li>&quot;Vertraue deinem Training&quot;</li><li>&quot;Das hast du schon einmal gemacht.&quot;</li><li>„Bleibe im Hier und Jetzt.“</li><li>&quot;Durchatmen und neu starten&quot;</li></ul><h3 id="tagliche-ubung" tabindex="-1">Tägliche Übung <a class="header-anchor" href="#tagliche-ubung" aria-label="Permalink to &quot;Tägliche Übung&quot;">​</a></h3><p>Nehmen Sie sich täglich 5 Minuten Zeit:</p><ol><li>Erinnere dich an einen Moment, in dem du eine gute Leistung erbracht hast.</li><li>Erinnere dich daran, wie es sich in deinem Körper angefühlt hat.</li><li>Hören Sie, was Ihre unterstützende Stimme gesagt hat.</li><li>Verankern Sie dieses Gefühl mit einer körperlichen Geste (Berühren der Boulekugel, Anpassen der Körperhaltung).</li></ol><h2 id="im-wettbewerb" tabindex="-1">Im Wettbewerb <a class="header-anchor" href="#im-wettbewerb" aria-label="Permalink to &quot;Im Wettbewerb&quot;">​</a></h2><p>Wenn der innere Kritiker während eines Spiels auftaucht:</p><ol><li><strong>Erkenne es an:</strong> „Ich merke, dass ich selbstkritisch bin.“</li><li><strong>Tief durchatmen</strong>: Langsames, tiefes Einatmen zum Zurücksetzen</li><li><strong>Nutze deinen Anker</strong>: Die körperliche Geste aus deiner Praxis</li><li><strong>Zurück zur Routine</strong>: Konzentrieren Sie sich auf Ihre Vorbereitungsphase.</li></ol><h2 id="die-langzeitreise" tabindex="-1">Die Langzeitreise <a class="header-anchor" href="#die-langzeitreise" aria-label="Permalink to &quot;Die Langzeitreise&quot;">​</a></h2><p>Den inneren Kritiker zu zähmen, ist keine einmalige Angelegenheit. Es ist ein fortlaufender Prozess, der mit der Zeit leichter wird. Spitzensportler eliminieren Selbstzweifel nicht – sie lernen, trotz ihnen Höchstleistungen zu erbringen.</p><p>Der innere Kritiker wird immer ein Teil von dir sein. Doch mit Übung wird seine Stimme leiser und deine unterstützende Stimme stärker. Das ist der mentale Vorteil, der gute Spieler von großartigen unterscheidet.</p><hr><p>| <em>Verwandtes Thema: <a href="/en/education/mental-strength/handling-pressure">Umgang mit Druck</a> | <a href="/en/education/mental-strength/pre-shot-routine">Vorbereitungsroutine vor der Impfung</a> | <a href="/en/education/mindfulness/techniques">Achtsamkeitstechniken</a></em> |</p>',43)])])}]]);export{t as __pageData,a as default};
